Dictionary<string, int> CountWords(IEnumerable<string> words) {
    var counts = new Dictionary<string, int>();
    foreach (var w in words) {
        counts.TryGetValue(w, out var cur);
        counts[w] = cur + 1;
    }
    return counts;
}

def deduplicate_events(events):
    seen = []
    result = []
    for event in events:
        eid = event['event_id']
        if eid not in seen:
            seen.append(eid)
            result.append(event)
